/**
 * Calculate late fee for an invoice: 0.04% of amount due per day overdue.
 * @param {{ dueDate: string, status: string, payments?: Array, lines: Array }} invoice
 * @param {string} asOf - YYYY-MM-DD format
 * @returns {number}
 */
export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const amountDue = balanceDue(invoice);
  if (amountDue <= 0) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const fee = roundCents(amountDue * 0.0004 * daysOverdue);
  return Math.max(0, fee);
}

/**
 * Get dashboard metrics for invoices.
 * @param {Array<{ customerId: string, status: string, dueDate: string, payments?: Array, lines: Array }>} invoices
 * @param {string} asOf - YYYY-MM-DD format
 * @returns {{ counts: { draft: number, issued: number, partially_paid: number, paid: number }, outstanding: number, overdue: { count: number, amount: number }, topCustomers: Array<{ customerId: string, due: number }> }}
 */
export function dashboard(invoices, asOf) {
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  let outstanding = 0;
  const customerDueMap = new Map();

  for (const invoice of invoices) {
    counts[invoice.status] = (counts[invoice.status] ?? 0) + 1;

    if (invoice.status === 'issued' || invoice.status === 'partially_paid') {
      const due = balanceDue(invoice);
      outstanding += due;

      if (due > 0) {
        const current = customerDueMap.get(invoice.customerId) ?? 0;
        customerDueMap.set(invoice.customerId, current + due);
      }
    }
  }

  const overdue = overdueInvoices(invoices, asOf);
  const overdueAmount = overdue.reduce((sum, inv) => sum + inv.due, 0);

  const topCustomers = Array.from(customerDueMap)
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue: { count: overdue.length, amount: overdueAmount },
    topCustomers,
  };
}

