import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee } from '../src/reports.js';

test('overdueInvoices returns empty array when no invoices provided', () => {
  const result = overdueInvoices([], '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices filters out draft invoices', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST-A',
      status: 'draft',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices filters out paid invoices', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST-A',
      status: 'paid',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoices', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST-A',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-15');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-001');
});

test('overdueInvoices includes partially_paid invoices', () => {
  const invoices = [
    {
      number: 'INV-002',
      customerId: 'CUST-B',
      status: 'partially_paid',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 300, date: '2026-10-05' }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-15');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-002');
});

test('overdueInvoices filters out invoices not yet due', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST-A',
      status: 'issued',
      dueDate: '2026-10-20',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices filters out invoices due exactly on asOf date', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST-A',
      status: 'issued',
      dueDate: '2026-10-15',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-15');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes invoices due one day before asOf', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST-A',
      status: 'issued',
      dueDate: '2026-10-14',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-15');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST-A',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-15');
  assert.equal(result[0].daysOverdue, 14);
});

test('overdueInvoices calculates due amount for fully unpaid issued invoice', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST-A',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-15');
  assert.equal(result[0].due, 1000);
});

test('overdueInvoices calculates due amount for partially paid invoice', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'CUST-A',
